import{_ as a,o as i,c as e,ag as s}from"./chunks/framework.NIGIbcGl.js";const g=JSON.parse('{"title":"Mitra Registration Guide","description":"","frontmatter":{},"headers":[],"relativePath":"customer/mitra-registration/index.md","filePath":"customer/mitra-registration/index.md"}'),o={name:"customer/mitra-registration/index.md"};function n(r,t,d,p,l,h){return i(),e("div",null,[...t[0]||(t[0]=[s(`<h1 id="mitra-registration-guide" tabindex="-1">Mitra Registration Guide <a class="header-anchor" href="#mitra-registration-guide" aria-label="Permalink to &quot;Mitra Registration Guide&quot;">​</a></h1><p>Self-serve onboarding for <strong>Mitra</strong> (partner) applicants. A mitra registers, uploads documents, and — once an admin approves — is issued a per-tier registration number (<code>MS.</code> / <code>MG.</code>) and the pricing access for their tier.</p><blockquote><p><strong>Mitra vs B2B vs Partner.</strong> Mitra is a <strong>customer-onboarding</strong> flow, distinct from the admin-provisioned banking <strong>Partner</strong> API-key module and from the <strong>B2B</strong> KYC flow (which requires NIB/NPWP). Individuals with no company documents can register as mitra.</p></blockquote><hr><h2 id="quick-overview" tabindex="-1">Quick Overview <a class="header-anchor" href="#quick-overview" aria-label="Permalink to &quot;Quick Overview&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tier</th><th>Prefix</th><th>On approval</th></tr></thead><tbody><tr><td>Mitra Silver</td><td><code>MS.</code></td><td>Promo pricing access</td></tr><tr><td>Mitra Gold</td><td><code>MG.</code></td><td>Promo + special-B2B pricing access</td></tr></tbody></table><p><strong>Who can apply:</strong> anyone. You do <strong>not</strong> need an organization.</p><h2 id="the-organization-form-is-optional" tabindex="-1">The organization form is optional <a class="header-anchor" href="#the-organization-form-is-optional" aria-label="Permalink to &quot;The organization form is optional&quot;">​</a></h2><p><code>companyName</code> (with the optional <code>companyAddress</code>) <strong>is</strong> the organization form, and it decides what approval creates:</p><table tabindex="0"><thead><tr><th>You supply <code>companyName</code></th><th>On approval you get</th></tr></thead><tbody><tr><td><strong>Yes</strong></td><td>An <strong>Organization</strong> + a SAR organization wallet, and your account is promoted to a <code>B2B</code> member of it. The tier flags live on the organization.</td></tr><tr><td><strong>No</strong> (blank / omitted)</td><td><strong>No organization.</strong> You are an <strong>individual partner</strong>: your account stays <code>B2C</code> and the tier + promo flags are set on <strong>you</strong>. Pricing is identical — a Gold individual partner gets the same special pricing a Gold organization gets.</td></tr></tbody></table><p>Blank and whitespace-only values count as <strong>not supplied</strong> — an empty text input is the same as omitting the field.</p><p>Two rules follow from this:</p><ul><li><strong><code>applicantType: COMPANY</code> requires <code>companyName</code>.</strong> Declaring yourself a company and then not naming one is rejected with <code>400</code>.</li><li><code>applicantType: INDIVIDUAL</code> <strong>may</strong> still supply a <code>companyName</code> (a sole proprietor who wants an organization). The two fields are independent: <code>applicantType</code> decides whether a <strong>KTP</strong> is required; <code>companyName</code> decides whether an <strong>Organization</strong> is created.</li></ul><table tabindex="0"><thead><tr><th><code>applicantType</code></th><th>organization form</th><th>KTP required</th><th>Organization created</th></tr></thead><tbody><tr><td><code>INDIVIDUAL</code></td><td>blank</td><td>yes</td><td><strong>no</strong> — individual partner</td></tr><tr><td><code>INDIVIDUAL</code></td><td>filled</td><td>yes</td><td>yes (sole proprietor)</td></tr><tr><td><code>COMPANY</code></td><td>blank</td><td>no</td><td><strong>400 — rejected</strong></td></tr><tr><td><code>COMPANY</code></td><td>filled</td><td>no</td><td>yes</td></tr></tbody></table><hr><h2 id="required-documents" tabindex="-1">Required Documents <a class="header-anchor" href="#required-documents" aria-label="Permalink to &quot;Required Documents&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Document</th><th>Required for</th><th>Accepted types</th></tr></thead><tbody><tr><td>SPK</td><td>All applicants</td><td>PDF, DOCX</td></tr><tr><td>KTP</td><td><code>INDIVIDUAL</code> only</td><td>JPEG, PNG, WebP, PDF</td></tr><tr><td>Partnership file</td><td>All applicants</td><td>PDF, DOCX, JPEG, PNG, WebP</td></tr><tr><td>Payment proof</td><td>All applicants — <code>SILVER</code> (100 SAR), <code>GOLD</code> (50,000 SAR)</td><td>PDF, JPEG, PNG, WebP</td></tr></tbody></table><p>Max upload size: 10 MB per file.</p><blockquote><p>The <strong>Gold 50,000 SAR deposit</strong> proof <strong>is</strong> captured here (uploaded as the payment proof). The deposit transfer itself is verified manually by an admin off-system and is <strong>not</strong> credited to your wallet balance.</p></blockquote><hr><h2 id="api-endpoints" tabindex="-1">API Endpoints <a class="header-anchor" href="#api-endpoints" aria-label="Permalink to &quot;API Endpoints&quot;">​</a></h2><h3 id="base-url" tabindex="-1">Base URL <a class="header-anchor" href="#base-url" aria-label="Permalink to &quot;Base URL&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://&lt;host&gt;/api/v1</span></span></code></pre></div><h3 id="_1-submit-a-registration" tabindex="-1">1. Submit a registration <a class="header-anchor" href="#_1-submit-a-registration" aria-label="Permalink to &quot;1. Submit a registration&quot;">​</a></h3><p><strong>Endpoint:</strong> <code>POST /auth/mitra/register</code></p><p><strong>Authentication:</strong> Optional. Unauthenticated submissions resolve or create a passwordless account from the applicant email/phone (login later via OTP).</p><p><strong>Request Body:</strong></p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;tier&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;SILVER&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;applicantType&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;COMPANY&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;applicantName&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Budi Santoso&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;applicantEmail&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;budi@example.com&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;applicantPhone&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;+6281234567890&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;companyName&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;PT Mitra Sejahtera&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;companyAddress&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Jl. Merdeka No. 1, Jakarta&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;spkNumber&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;05.123/ADI/07/2026&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><ul><li><code>spkNumber</code> is optional but, when supplied, must match <code>05.XXX/ADI/MM/YYYY</code>.</li><li><code>companyName</code> / <code>companyAddress</code> are the <strong>optional organization form</strong> — see above. Omit both to register as an individual partner with no organization:</li></ul><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;tier&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;GOLD&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;applicantType&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;INDIVIDUAL&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;applicantName&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Siti Aminah&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;applicantEmail&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;siti@example.com&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;applicantPhone&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;+6281234567891&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><strong>Response:</strong> <code>201 Created</code> — the created registration (<code>status: &quot;PENDING&quot;</code>).</p><p><strong>Errors:</strong></p><table tabindex="0"><thead><tr><th>Code</th><th>When</th></tr></thead><tbody><tr><td><code>400</code></td><td><code>applicantType: &quot;COMPANY&quot;</code> with no <code>companyName</code>.</td></tr><tr><td><code>409</code></td><td>An open registration already exists for this applicant, <strong>or</strong> the account already has an <strong>approved</strong> registration (one approved registration per account, ever).</td></tr><tr><td><code>409</code></td><td>The email/phone belongs to an existing B2B or admin account — sign in and manage that organization instead.</td></tr></tbody></table><h3 id="_2-upload-a-document" tabindex="-1">2. Upload a document <a class="header-anchor" href="#_2-upload-a-document" aria-label="Permalink to &quot;2. Upload a document&quot;">​</a></h3><p><strong>Endpoint:</strong> <code>POST /auth/mitra/register/:id/upload/:docType</code></p><p><code>docType ∈ { spk, ktp, partnership, payment-proof }</code>. Multipart form field <code>file</code>.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$BASE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/auth/mitra/register/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$ID</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/upload/spk&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -F</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;file=@SPK.pdf&quot;</span></span></code></pre></div><p><strong>Response:</strong> <code>201 Created</code> — the updated registration with the document linked.</p><blockquote><p>If the registration already carries a valid <code>spkNumber</code>, the uploaded SPK&#39;s display filename is set to the number (e.g. <code>05.123_ADI_07_2026.pdf</code>).</p></blockquote><h3 id="_3-check-registration-status" tabindex="-1">3. Check registration status <a class="header-anchor" href="#_3-check-registration-status" aria-label="Permalink to &quot;3. Check registration status&quot;">​</a></h3><p><strong>Endpoint:</strong> <code>GET /auth/mitra/application/status</code></p><p><strong>Authentication:</strong> Bearer JWT (the applicant&#39;s account).</p><p><strong>Response:</strong> <code>200 OK</code> — the applicant&#39;s latest registration record.</p><hr><h2 id="post-approval" tabindex="-1">Post-Approval <a class="header-anchor" href="#post-approval" aria-label="Permalink to &quot;Post-Approval&quot;">​</a></h2><p>Both kinds of partner receive:</p><ul><li>a per-tier <strong>registration number</strong> (<code>MS.001</code> … <code>MS.999</code> … <code>MS.1000</code>, likewise <code>MG.</code>) — drawn from one shared per-tier counter, so organization and individual partners are numbered in the same sequence;</li><li>the tier&#39;s pricing access (Gold ⇒ special + promo; Silver ⇒ promo);</li><li>an approval email.</li></ul><p>What differs:</p><table tabindex="0"><thead><tr><th></th><th>Organization partner</th><th>Individual partner</th></tr></thead><tbody><tr><td>Organization</td><td>created</td><td><strong>none</strong></td></tr><tr><td>Organization wallet</td><td>created (SAR, balance <code>0</code>)</td><td><strong>none</strong></td></tr><tr><td>Account role</td><td>promoted to <code>B2B</code></td><td>stays <code>B2C</code></td></tr><tr><td>Where the tier lives</td><td>on the organization</td><td>on <strong>your account</strong></td></tr><tr><td>Personal SAR wallet</td><td>yes (created at registration)</td><td>yes (created at registration)</td></tr><tr><td>Approval email</td><td>shows an organization code</td><td>omits the organization-code row</td></tr></tbody></table><p>Your personal SAR wallet is created when you <strong>register</strong>, not at approval, so the wallet endpoints work from submission onward.</p><blockquote><p><strong>A Gold individual partner still owes the 50,000 SAR deposit.</strong> The deposit is keyed on the tier, not on whether you have a company. It is verified manually by an admin off-system and is <strong>not</strong> credited to any wallet balance.</p></blockquote><blockquote><p><strong>One approved registration per account, ever.</strong> After approval you cannot submit another registration (<code>409</code>) — including to change tier. Contact an admin instead.</p></blockquote><hr><h2 id="related-documentation" tabindex="-1">Related Documentation <a class="header-anchor" href="#related-documentation" aria-label="Permalink to &quot;Related Documentation&quot;">​</a></h2><ul><li><a href="/ahlaan-train-docs/customer/register-login/">Registration &amp; Login</a></li><li><a href="/ahlaan-train-docs/customer/b2b-registration/">B2B Registration Guide</a></li></ul>`,55)])])}const u=a(o,[["render",n]]);export{g as __pageData,u as default};
